"""`t0 gen [--check] [--scope plugin|kb] [--src DIR] [--out DIR]`: every generated file, from one TARGETS table.

Hand-written inputs (the only sources):
  pyproject.toml                  version + description -> both plugin manifests
  plugin/skills/<name>/SKILL.md   skills (copied verbatim to .kiro/skills/)
  plugin/.mcp.json                the one MCP server declaration (mcpServers)
  t0.hooks.HOOKS                  hook table -> Claude, Copilot and Kiro registrations
  t0.profile.table                TYPES/GATES/BET_TYPES -> KB profile.md

`--check` renders to memory, diffs against disk and exits 1 listing drifted paths. Markdown outputs
carry a generated marker; JSON manifests do not (strict validators reject unknown keys).
"""
from __future__ import annotations

import json
import re
import sys
import tomllib
from dataclasses import dataclass, field
from datetime import datetime, timezone
from enum import Enum
from pathlib import Path
from typing import Any, Callable

from .hooks import HOOKS

MARKER = "<!-- generated by t0 gen; edit the source -->"
PLUGIN_NAME = "t0"
KEYWORDS = ["t0", "aidlc", "okf", "knowledge-base", "jira", "methodology"]
AGENT_PLUGINS_SCHEMA = "https://agent-plugins.org/schemas/1.0/plugin.json"   # unverified URL
HOOK_TIMEOUT_S = 10
_TOOLKIT = Path(__file__).resolve().parents[2]


class Tool(Enum):
    CLAUDE = "claude"; COPILOT = "copilot"; KIRO = "kiro"; ALL = "all"


class Scope(Enum):
    PLUGIN = "plugin"; KB = "kb"


@dataclass(frozen=True)
class Sources:
    version: str
    description: str
    mcp_servers: dict[str, Any]
    skills: dict[str, dict[str, str]]       # skill name -> {relative path -> text}
    now: str


@dataclass(frozen=True)
class GenContext:
    root: Path                  # output directory
    scope: Scope
    src: Path | None = None     # plugin source dir (scope plugin)
    facts: dict[str, Any] = field(default_factory=dict)


Rendered = str | dict[str, str]   # one file, or (for a directory target) sub-path -> text


@dataclass(frozen=True)
class Target:
    tool: Tool
    scope: Scope
    path: str                   # relative to GenContext.root; a trailing '/' means a directory of files
    render: Callable[[Sources], Rendered]


class SourceError(Exception): ...


# ------------------------------------------------------------------ sources (boundary)


def load_sources(ctx: GenContext) -> Sources:
    py = tomllib.loads((Path(ctx.facts.get("pyproject", _TOOLKIT / "pyproject.toml"))).read_text(encoding="utf-8"))
    project = py["project"]
    now = ctx.facts.get("now") or datetime.now(timezone.utc).replace(microsecond=0).isoformat()
    if ctx.scope is Scope.KB:
        return Sources(project["version"], project["description"], {}, {}, now)
    src = ctx.src
    if src is None or not src.is_dir():
        raise SourceError(f"diretório fonte do plugin ausente: {src}")
    mcp_path = src / ".mcp.json"
    if not mcp_path.is_file():
        raise SourceError(f"fonte ausente: {mcp_path}")
    mcp = json.loads(mcp_path.read_text(encoding="utf-8"))
    if not isinstance(mcp.get("mcpServers"), dict) or not mcp["mcpServers"]:
        raise SourceError(f"{mcp_path} precisa de um mapa `mcpServers` não vazio")
    skills: dict[str, dict[str, str]] = {}
    for skill_md in sorted((src / "skills").glob("*/SKILL.md")):
        d = skill_md.parent
        skills[d.name] = {str(p.relative_to(d)): p.read_text(encoding="utf-8")
                          for p in sorted(d.rglob("*")) if p.is_file()}
    return Sources(project["version"], project["description"], mcp["mcpServers"], skills, now)


# ------------------------------------------------------------------ renderers


def _json(obj: Any) -> str:
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def _cmd(name: str, tool: Tool | None = None) -> str:
    return f"t0 hook {name}" + (f" --tool {tool.value}" if tool else "")


def claude_manifest(s: Sources) -> str:
    return _json({"name": PLUGIN_NAME, "version": s.version, "description": s.description,
                  "author": {"name": "t0"}, "license": "MIT", "keywords": KEYWORDS})


def agent_plugins_manifest(s: Sources) -> str:
    return _json({"$schema": AGENT_PLUGINS_SCHEMA, "name": PLUGIN_NAME, "version": s.version,
                  "description": s.description, "author": {"name": "t0"}, "keywords": KEYWORDS})


def claude_hooks(s: Sources) -> str:
    events: dict[str, list[dict[str, Any]]] = {}
    for h in HOOKS:
        if h.claude is None:
            continue
        event, matcher = h.claude
        entry: dict[str, Any] = {"hooks": [{"type": "command", "command": _cmd(h.event.value), "timeout": HOOK_TIMEOUT_S}]}
        if matcher:
            entry = {"matcher": matcher, **entry}
        events.setdefault(event, []).append(entry)
    return _json({"hooks": events})


def copilot_hooks(s: Sources) -> str:
    events: dict[str, list[dict[str, Any]]] = {}
    for h in HOOKS:
        if h.copilot is None:
            continue
        cmd = _cmd(h.event.value, Tool.COPILOT)
        events.setdefault(h.copilot, []).append(
            {"type": "command", "bash": cmd, "powershell": cmd, "timeoutSec": HOOK_TIMEOUT_S})
    return _json({"version": 1, "hooks": events})


def kiro_hooks(s: Sources) -> str:
    hooks = [{"name": f"t0 {h.event.value}", "event": h.kiro[0], **({"matcher": h.kiro[1]} if h.kiro[1] else {}),
              "command": _cmd(h.event.value, Tool.KIRO), "timeout": HOOK_TIMEOUT_S}
             for h in HOOKS if h.kiro is not None]
    return _json({"version": "v1", "hooks": hooks})


def mcp_portable(s: Sources) -> str:
    return _json({"mcpServers": s.mcp_servers})


def vscode_mcp(s: Sources) -> str:
    return _json({"servers": {name: {"type": "stdio", **cfg} for name, cfg in s.mcp_servers.items()}})


def copilot_instructions(s: Sources) -> str:
    return (f"{MARKER}\n"
            "Leia o `AGENTS.md` da raiz: ele traz o card t0 (bet ativa, repos, regras do KB).\n"
            "Contexto do KB pelo MCP `t0-kb` (`kb_context`). Sem KB disponível, pare e diga \"KB indisponível\".\n")


def kiro_steering(s: Sources) -> str:
    return ("---\ninclusion: always\n---\n"
            f"{MARKER}\n"
            "Delta de frescor do card t0 (uma linha quando o AGENTS.md está em dia):\n\n"
            "#[[file:.t0/context.md]]\n")


def kiro_skills(s: Sources) -> dict[str, str]:
    return {f"{name}/{rel}": text for name, files in s.skills.items() for rel, text in files.items()}


# ------------------------------------------------------------------ profile.md (scope kb)


def _cell(x: object) -> str:
    return str(x).replace("|", "\\|").replace("\n", " ")


def _table(head: list[str], rows: list[list[object]]) -> list[str]:
    return ["| " + " | ".join(head) + " |", "|" + "---|" * len(head)] + ["| " + " | ".join(_cell(c) for c in r) + " |" for r in rows]


def profile_md(s: Sources) -> str:
    from .profile.table import BET_TYPES, COMMON_FIELDS, GATES, PROFILE, PROFILE_VERSION, STATEFUL_DERIVED, TYPES

    def derived(t: Any) -> str:
        keys = [f.name for f in t.fields if f.derived] + ([f.name for f in STATEFUL_DERIVED] if t.states else [])
        return ", ".join(sorted(keys)) or "-"

    lines = [
        "---", "type: OKF Profile", f'title: "Profile {PROFILE} {PROFILE_VERSION}"',
        'description: "Tipos, chaves, estados, gates e tipos de bet do profile t0-team; gerado pelo t0 gen."',
        "uid: profile-t0-team", "owner: process:t0-gen", "tags: [profile, gerado]",
        f'generated: {{ by: process:t0-gen, at: "{s.now}" }}',
        f"profile: {PROFILE}", f'profile_version: "{PROFILE_VERSION}"',
        "timestamps: offset-required", "link_style: bundle-absolute", "---", MARKER, "",
        f"# Profile {PROFILE} {PROFILE_VERSION}", "",
        "Gerado de `t0/profile/table.py` (toolkit " + s.version + "). Não edite: mude a tabela e rode `t0 gen --scope kb`.",
        "", "## Chaves comuns", ""]
    lines += _table(["chave", "tipo", "obrigatória", "o que é"],
                    [[f"`{f.name}`", f.kind.value, "sim" if f.required else "não", f.doc_pt or "-"] for f in COMMON_FIELDS])
    lines += ["", "## Tipos", ""]
    lines += _table(["tipo", "slug", "raia", "caminhos", "estados", "chaves derivadas"],
                    [[t.name, t.slug, t.lane.value, ", ".join(f"`{p}`" for p in t.paths),
                      ", ".join(t.states.status_of) if t.states else "-", derived(t)] for t in TYPES])
    lines += ["", "## Gates", ""]
    lines += _table(["gate", "nome", "alvo", "checks", "quem escreve"],
                    [[g.id, g.title_pt, g.target_type, ", ".join(c.value for c in g.checks) or "-", g.writer.value]
                     for g in GATES])
    lines += ["", "## Tipos de bet", ""]
    lines += _table(["tipo", "gates", "artefatos", "apetite máximo", "tier padrão", "eval"],
                    [[b.name, ", ".join(b.gates), ", ".join(b.artifacts), b.appetite_max, b.tier_default,
                      "sim" if b.eval_required else "não"] for b in BET_TYPES])
    return "\n".join(lines) + "\n"


# ------------------------------------------------------------------ the table

TARGETS: tuple[Target, ...] = (
    Target(Tool.CLAUDE, Scope.PLUGIN, ".claude-plugin/plugin.json", claude_manifest),
    Target(Tool.CLAUDE, Scope.PLUGIN, "hooks/hooks.json", claude_hooks),
    Target(Tool.ALL, Scope.PLUGIN, "plugin.json", agent_plugins_manifest),
    Target(Tool.ALL, Scope.PLUGIN, "mcp.json", mcp_portable),
    Target(Tool.COPILOT, Scope.PLUGIN, ".github/hooks/t0.json", copilot_hooks),
    Target(Tool.COPILOT, Scope.PLUGIN, ".vscode/mcp.json", vscode_mcp),
    Target(Tool.COPILOT, Scope.PLUGIN, ".github/copilot-instructions.md", copilot_instructions),
    Target(Tool.KIRO, Scope.PLUGIN, ".kiro/steering/t0.md", kiro_steering),
    Target(Tool.KIRO, Scope.PLUGIN, ".kiro/settings/mcp.json", mcp_portable),
    Target(Tool.KIRO, Scope.PLUGIN, ".kiro/hooks/t0.json", kiro_hooks),
    Target(Tool.KIRO, Scope.PLUGIN, ".kiro/skills/", kiro_skills),
    Target(Tool.ALL, Scope.KB, "profile.md", profile_md),
)

_VOLATILE = re.compile(r"^generated: \{ by: process:t0-gen, at: .*\}$", re.MULTILINE)


def _stable(text: str) -> str:
    return _VOLATILE.sub("generated: <t0-gen>", text)


@dataclass(frozen=True)
class Drift:
    path: str
    reason: str                 # 'missing' | 'differs'


def generate(ctx: GenContext) -> dict[str, str]:
    """Pure over the loaded sources: path -> content for every target of the scope."""
    s = load_sources(ctx)
    out: dict[str, str] = {}
    for t in TARGETS:
        if t.scope is not ctx.scope:
            continue
        r = t.render(s)
        if isinstance(r, str):
            out[t.path] = r
        else:
            out.update({t.path + sub: text for sub, text in r.items()})
    return out


def check_drift(ctx: GenContext, rendered: dict[str, str] | None = None) -> list[Drift]:
    rendered = generate(ctx) if rendered is None else rendered
    drift: list[Drift] = []
    for rel, text in sorted(rendered.items()):
        p = ctx.root / rel
        if not p.is_file():
            drift.append(Drift(rel, "missing"))
        elif _stable(p.read_text(encoding="utf-8")) != _stable(text):
            drift.append(Drift(rel, "differs"))
    return drift


def write(ctx: GenContext, rendered: dict[str, str]) -> list[str]:
    """Writes only drifted files (a timestamp-only difference is not drift). Returns written paths."""
    written: list[str] = []
    for d in check_drift(ctx, rendered):
        p = ctx.root / d.path
        p.parent.mkdir(parents=True, exist_ok=True)
        tmp = p.with_name(p.name + ".t0tmp")
        tmp.write_text(rendered[d.path], encoding="utf-8")
        tmp.replace(p)
        written.append(d.path)
    return written


def run(*, scope: str = "plugin", out: Path | None = None, src: Path | None = None, check: bool = False) -> int:
    """Entry for `t0 gen`. Exit 0 ok, 1 drift (with --check), 2 source error."""
    sc = Scope(scope)
    plugin_src = src or (_TOOLKIT.parent / "plugin")
    root = out or (plugin_src if sc is Scope.PLUGIN else Path.cwd())
    ctx = GenContext(root, sc, plugin_src)
    try:
        rendered = generate(ctx)
    except SourceError as e:
        print(f"t0 gen: {e}", file=sys.stderr)
        return 2
    if check:
        drift = check_drift(ctx, rendered)
        for d in drift:
            print(f"{d.reason}: {d.path}")
        return 1 if drift else 0
    for path in write(ctx, rendered):
        print(f"escrito: {path}")
    return 0


def main(argv: list[str] | None = None) -> int:
    import argparse

    ap = argparse.ArgumentParser(prog="t0 gen")
    ap.add_argument("--scope", choices=[s.value for s in Scope], default="plugin")
    ap.add_argument("--out", type=Path)
    ap.add_argument("--src", type=Path)
    ap.add_argument("--check", action="store_true")
    a = ap.parse_args(argv)
    return run(scope=a.scope, out=a.out, src=a.src, check=a.check)


if __name__ == "__main__":
    raise SystemExit(main())
